# Für HL7-Felder:
# PID_5=Patientenname
# PID_7=Geburtsdatum
# OBX_5=Laborwert Resultat

# Für Text-/CSV-Dateien:
# Feld 1=Auftragsnummer
# Feld 2=Kundenname
# Feld 3=Erstellungsdatum

Feld 1 = [Gruppe][Leistungsnummer]
Feld 11 = Gruppe
Feld 29 = Hier wird entweder <leer>, RKB, KSA, KSA+RKB geliefert
